from queueing import payload
def submit(owner, enqueue, mode="all"):
    return enqueue(payload(owner, mode))

def payload(owner, mode="all"):
    if mode not in ["all", "remote", "hybrid", "office"]:
        raise ValueError(f"Invalid mode: {mode}. Must be all, remote, hybrid, or office.")
    return {"owner": owner, "mode": mode}

def execute(task, jobs):
    # Default missing legacy mode to all
    if task.get('mode') is None:
        task['mode'] = 'all'

    # Get the filter mode from task
    mode = task.get('mode', 'all')

    # Filter jobs based on mode
    # Unknown job mode (missing or None) means stay included for every filter
    # Input job modes otherwise belong to remote/hybrid/office
    filtered_jobs = []
    for job in jobs:
        job_mode = job.get('mode')

        if job_mode is None:
            # Include jobs with missing mode
            filtered_jobs.append(job)
        elif mode == 'all':
            # Include all jobs
            filtered_jobs.append(job)
        elif mode == 'remote':
            if job_mode == 'remote':
                filtered_jobs.append(job)
        elif mode == 'hybrid':
            if job_mode == 'hybrid':
                filtered_jobs.append(job)
        elif mode == 'office':
            if job_mode == 'office':
                filtered_jobs.append(job)

    return filtered_jobs
